<script setup>
import { onMounted, reactive, ref } from 'vue';
import { useRoute } from 'vue-router';
import { axios } from '../../lib/echo';
import { useHubStore } from '../../stores/hub';

const store = useHubStore(); const route = useRoute(); const hubs = ref([]); const showForm = ref(Boolean(route.query.order_ids || route.query.new)); const selected = ref((route.query.order_ids || '').split(',').filter(Boolean).map(Number)); const form = reactive({ from_hub_id: route.query.from_hub_id || '', to_hub_id: '', notes: '' }); const error = ref('');
const badge = { pending: 'bg-amber-100 text-amber-800', approved: 'bg-blue-100 text-blue-800', rejected: 'bg-red-100 text-red-800', in_transit: 'bg-sky-100 text-sky-800', completed: 'bg-emerald-100 text-emerald-800' };
const label = (value) => value.replaceAll('_', ' ');
const load = async () => { store.auth(); hubs.value = (await axios.get('/hubs')).data; await store.fetchTransfers(); };
const create = async () => { error.value = ''; try { await store.createTransfer({ ...form, order_ids: selected.value }); showForm.value = false; selected.value = []; await store.fetchTransfers(); } catch (e) { error.value = e.response?.data?.message || 'Transfer request could not be created.'; } };
const update = async (item, status) => { try { await store.updateTransferStatus(item.id, status); await store.fetchTransfers(); } catch (e) { error.value = e.response?.data?.message || 'Workflow update failed.'; } };
onMounted(load);
</script>

<template>
  <main class="min-h-screen bg-[#f4f7f6] text-slate-900"><header class="border-b border-slate-200 bg-white"><div class="mx-auto max-w-7xl px-6 py-6"><p class="text-xs font-black uppercase tracking-widest text-teal-700">Network logistics</p><div class="mt-1 flex flex-wrap items-center justify-between gap-4"><h1 class="text-3xl font-black">Transfer requests</h1><button class="bg-slate-950 px-5 py-3 text-sm font-bold text-white" @click="showForm = true">New transfer request</button></div></div></header><div class="mx-auto max-w-7xl px-6 py-8"><p v-if="error" class="mb-4 bg-red-50 px-4 py-3 text-sm text-red-700">{{ error }}</p><section class="border border-slate-200 bg-white shadow-sm"><div class="overflow-x-auto"><table class="w-full min-w-[850px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-3">Reference</th><th class="px-5 py-3">Route</th><th class="px-5 py-3">Packages</th><th class="px-5 py-3">Status</th><th class="px-5 py-3 text-right">Workflow</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="item in store.transfers.data" :key="item.id"><td class="px-5 py-4 font-mono font-bold">{{ item.reference_number }}</td><td class="px-5 py-4">{{ item.from_hub?.name }} <span class="text-slate-400">→</span> {{ item.to_hub?.name }}</td><td class="px-5 py-4">{{ item.items?.length || 0 }}</td><td class="px-5 py-4"><span class="px-2.5 py-1 text-xs font-bold capitalize" :class="badge[item.status]">{{ label(item.status) }}</span></td><td class="space-x-3 px-5 py-4 text-right"><button v-if="item.status === 'pending'" class="font-bold text-blue-700" @click="update(item, 'approved')">Approve</button><button v-if="item.status === 'approved'" class="font-bold text-sky-700" @click="update(item, 'in_transit')">Dispatch</button><button v-if="item.status === 'in_transit'" class="font-bold text-emerald-700" @click="update(item, 'completed')">Confirm arrival</button></td></tr><tr v-if="!store.transfers.data.length"><td colspan="5" class="p-12 text-center text-slate-400">No transfer requests yet.</td></tr></tbody></table></div></section></div><div v-if="showForm" class="fixed inset-0 z-30 flex items-center justify-center bg-slate-950/50 p-4" @click.self="showForm = false"><form class="w-full max-w-xl bg-white p-6 shadow-2xl" @submit.prevent="create"><div class="flex justify-between"><div><p class="text-xs font-black uppercase tracking-widest text-teal-700">Inter-hub movement</p><h2 class="mt-1 text-2xl font-black">Request transfer</h2></div><button type="button" class="text-2xl text-slate-400" @click="showForm = false">&times;</button></div><div class="mt-6 grid gap-4 sm:grid-cols-2"><label class="text-sm font-bold">Source hub<select v-model="form.from_hub_id" required class="mt-1 w-full border px-3 py-2"><option value="">Choose source</option><option v-for="hub in hubs" :key="hub.id" :value="hub.id">{{ hub.name }}</option></select></label><label class="text-sm font-bold">Destination hub<select v-model="form.to_hub_id" required class="mt-1 w-full border px-3 py-2"><option value="">Choose destination</option><option v-for="hub in hubs" :key="hub.id" :value="hub.id">{{ hub.name }}</option></select></label></div><label class="mt-4 block text-sm font-bold">Reason / notes<textarea v-model="form.notes" rows="4" required class="mt-1 w-full border px-3 py-2" placeholder="Why should these packages move?" /></label><div class="mt-4 bg-slate-50 p-4 text-sm text-slate-600">Selected package IDs: <strong>{{ selected.length ? selected.join(', ') : 'None' }}</strong></div><footer class="mt-6 flex justify-end gap-3"><button type="button" class="px-4 py-2 text-sm font-bold text-slate-600" @click="showForm = false">Cancel</button><button :disabled="!selected.length" class="bg-slate-950 px-5 py-2 text-sm font-bold text-white disabled:opacity-40">Create request</button></footer></form></div></main>
</template>